:root {
  /* Colors */
  --color-jet-canvas: #000000;
  --color-frosted-glass: #d8f4f609;
  --color-paper-white: #ffffff;
  --color-graphite-gutter: #464a4d;
  --color-iron-caption: #6c6c6c;
  --color-pewter-code: #a0a0a0;
  --color-ash-body: #a1a4a5;
  --color-fog-ink: #f0f0f0;
  --color-mist-title: #fcfdffef;
  --color-frosted-border: #d6ebfd30;
  --color-sunbeam-string: #ffff92;
  --color-mint-signal: #46fea5d4;
  --color-amber-signal: #ffca16;

  /* Typography — Font Families */
  --font-abc-favorit: "ABC Favorit", "Geist", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-commit-mono: "Commit Mono", "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-domaine: "Domaine Display", "Newsreader", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.33;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.33;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-heading-sm: 20px;
  --leading-heading-sm: 1.3;
  --tracking-heading-sm: 0px;
  --text-heading: 56px;
  --leading-heading: 1.2;
  --tracking-heading: -2.8px;
  --text-display: 96px;
  --leading-display: 1;
  --tracking-display: -0.96px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-96: 96px;
  --spacing-144: 144px;

  /* Layout */
  --layout-max-width: 1280px;
  --layout-section-gap: 96px;
  --layout-card-padding: 24px;
  --layout-element-gap: 16px;
  --layout-nav-height: 58px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 10px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 24px;
  --radius-sections: 24px;
  --radius-buttons: 16px;
  --radius-images: 16px;
  --radius-inner-tiles: 10px;
  --radius-small-elements: 6px;
  --radius-badges: 6px;
  --radius-tags: 4px;
  --radius-pills: 9999px;
  --radius-avatars: 9999px;

  /* Shadows */
  --shadow-subtle: 0 0 0 1px rgba(24, 25, 28, 0.88);
  --shadow-subtle-2: 0 0 0 8px #000000;
  --shadow-sm: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px -1px rgba(0, 0, 0, 0.1);

  /* Surfaces */
  --surface-jet-canvas: #000000;
  --surface-frosted-glass: #d8f4f609;
  --surface-frosted-border: #d6ebfd30;
  --surface-paper-white: #ffffff;
}

